/bin/bash -lc "cat > scores.sql <<'SQL'
USE isupipe;
CREATE TABLE IF NOT EXISTS user_scores (user_id BIGINT PRIMARY KEY, score BIGINT NOT NULL DEFAULT 0, INDEX score_index(score,user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS livestream_scores (livestream_id BIGINT PRIMARY KEY, score BIGINT NOT NULL DEFAULT 0, INDEX score_index(score,livestream_id)) ENGINE=InnoDB;
INSERT INTO user_scores(user_id,score) SELECT u.id,COALESCE(r.score,0)+COALESCE(c.score,0) FROM users u LEFT JOIN (SELECT l.user_id,COUNT(*) score FROM reactions r JOIN livestreams l ON l.id=r.livestream_id GROUP BY l.user_id) r ON r.user_id=u.id LEFT JOIN (SELECT l.user_id,SUM(c.tip) score FROM livecomments c JOIN livestreams l ON l.id=c.livestream_id GROUP BY l.user_id) c ON c.user_id=u.id ON DUPLICATE KEY UPDATE score=VALUES(score);
INSERT INTO livestream_scores(livestream_id,score) SELECT l.id,COALESCE(r.score,0)+COALESCE(c.score,0) FROM livestreams l LEFT JOIN (SELECT livestream_id,COUNT(*) score FROM reactions GROUP BY livestream_id) r ON r.livestream_id=l.id LEFT JOIN (SELECT livestream_id,SUM(tip) score FROM livecomments GROUP BY livestream_id) c ON c.livestream_id=l.id ON DUPLICATE KEY UPDATE score=VALUES(score);
DROP TRIGGER IF EXISTS user_score_insert;
DROP TRIGGER IF EXISTS livestream_score_insert;
DROP TRIGGER IF EXISTS comment_score_insert;
DROP TRIGGER IF EXISTS comment_score_delete;
DROP TRIGGER IF EXISTS reaction_score_insert;
DELIMITER //
CREATE TRIGGER user_score_insert AFTER INSERT ON users FOR EACH ROW BEGIN
 INSERT INTO user_scores(user_id) VALUES(NEW.id);
END//
CREATE TRIGGER livestream_score_insert AFTER INSERT ON livestreams FOR EACH ROW BEGIN
 INSERT INTO livestream_scores(livestream_id) VALUES(NEW.id);
END//
CREATE TRIGGER comment_score_insert AFTER INSERT ON livecomments FOR EACH ROW BEGIN
 IF NEW.tip <> 0 THEN
 UPDATE livestream_scores SET score=score+NEW.tip WHERE livestream_id=NEW.livestream_id;
 UPDATE user_scores SET score=score+NEW.tip WHERE user_id=(SELECT user_id FROM livestreams WHERE id=NEW.livestream_id);
 END IF;
END//
CREATE TRIGGER comment_score_delete AFTER DELETE ON livecomments FOR EACH ROW BEGIN
 IF OLD.tip <> 0 THEN
 UPDATE livestream_scores SET score=score-OLD.tip WHERE livestream_id=OLD.livestream_id;
 UPDATE user_scores SET score=score-OLD.tip WHERE user_id=(SELECT user_id FROM livestreams WHERE id=OLD.livestream_id);
 END IF;
END//
CREATE TRIGGER reaction_score_insert AFTER INSERT ON reactions FOR EACH ROW BEGIN
 UPDATE livestream_scores SET score=score+1 WHERE livestream_id=NEW.livestream_id;
 UPDATE user_scores SET score=score+1 WHERE user_id=(SELECT user_id FROM livestreams WHERE id=NEW.livestream_id);
END//
DELIMITER ;
SQL
cat > /tmp/ranks.py <<'PY'
from pathlib import Path
p=Path('go/stats_handler.go');s=p.read_text();a=s.index('\\tvar ranking UserRanking');b=s.index('\\n\\t// リアクション数',a)
s=s[:a]+'''	var score, rank int64
	if err:=tx.GetContext(ctx,&score,\"SELECT score FROM user_scores WHERE user_id=?\",user.ID);err"'!=nil{return err}
	if err:=tx.GetContext(ctx,&rank,`SELECT 1+COUNT(*) FROM user_scores s JOIN users u ON u.id=s.user_id WHERE s.score>? OR (s.score=? AND u.name>?)`,score,score,username);err!=nil{return err}
'"'''+s[b:]
a=s.index('\\tvar ranking LivestreamRanking');b=s.index('\\n\\t// 視聴者数算出',a)
s=s[:a]+'''	var score, rank int64
	if err:=tx.GetContext(ctx,&score,\"SELECT score FROM livestream_scores WHERE livestream_id=?\",livestreamID);err"'!=nil{return err}
	if err:=tx.GetContext(ctx,&rank,`SELECT 1+COUNT(*) FROM livestream_scores WHERE score>? OR (score=? AND livestream_id>?)`,score,score,livestreamID);err!=nil{return err}
'"'''+s[b:];p.write_text(s)
p=Path('sql/init.sql');s=p.read_text();s='TRUNCATE TABLE user_scores;\\nTRUNCATE TABLE livestream_scores;\\n'+s;p.write_text(s)
PY
