 for _,u:=range users {cache.freshUsers[u.ID]=true;cache.users[u.ID]=User{ID:u.ID,Name:u.Name,DisplayName:u.DisplayName,Description:u.Description,Theme:Theme{ID:u.ThemeID,DarkMode:u.DarkMode},IconHash:u.IconHash}}

 return nil
}
func preloadStreams(ctx context.Context,tx *sqlx.Tx, models []*LivestreamModel) error {
